namespace docking.options.editor;







using docking;
using docking.action;
using docking.widgets;
using ghidra.framework.options;

/**
 * Dialog for editing options within a tool.
 */
public class OptionsDialog : ReusableDialogComponentProvider {

	public static readonly string OPTIONS_OWNER = "Tool Options";
	public static readonly string TOGGLE_EDITOR_ACTION_NAME = "Toggle Editor";

	private OptionsPanel panel;
	private bool hasChanges;

	private OptionsEditorListener listener;

	/**
	 * Construct a new OptionsDialog.
	 *
	 * @param title dialog title
	 * @param rootNodeName name to display for the root node in the tree
	 * @param options editable options
	 * @param listener listener notified when the apply button is hit.
	 */
	public OptionsDialog(string title, string rootNodeName, Options[] options,
			OptionsEditorListener listener) : this(title, rootNodeName, options, listener, false)
    {
	}

	public OptionsDialog(string title, string rootNodeName, Options[] options,
			OptionsEditorListener listener, bool showRestoreDefaultsButton) : base("Options Dialog", true, false, true, false)
    {
		this.listener = listener;
		panel = new OptionsPanel(rootNodeName, options, showRestoreDefaultsButton,
			new OptionsPropertyChangeListener());

		setTitle(title);
		panel.getAccessibleContext().setAccessibleName("Options");
		addWorkPanel(panel);
		addOKButton();
		addCancelButton();
		addApplyButton();
		setApplyEnabled(false);
		setMinimumSize(1000, 600);

		setFocusComponent(panel.getFocusComponent());

		List<DockingAction> actions = panel.getActions();
		foreach (DockingAction action in actions) {
			addAction(action);
		}
	}

	/* @Override */
	public void dispose() {
		base.dispose();
		panel.dispose();
	}

	public TreePath getSelectedPath() {
		return panel.getSelectedPath();
	}

	public void setSelectedPath(TreePath path) {
		panel.setSelectedPath(path);
	}

	private void setHasChanges(bool hasChanges) {
		this.hasChanges = hasChanges;
		setApplyEnabled(hasChanges);
	}

	/* @Override */
	protected void cancelCallback() {
		// stop any active editors
		panel.cancel();

		if (hasChanges) {

			int result = OptionDialog.showOptionDialog(panel, "Save Options Changes?",
				"These options have changed.  Do you want to save them?",
				"Save", "Don't Save", OptionDialog.QUESTION_MESSAGE);
			if (result == OptionDialog.CANCEL_OPTION) {
				return;
			}

			if (result == OptionDialog.OPTION_ONE) { // Save
				if (!applyChanges()) {
					return;
				}
			}
		}
		close();
	}

	/* @Override */
	protected void okCallback() {
		if (hasChanges) {
			if (!applyChanges()) {
				return; // don't close on failure
			}
		}
		close();
	}

	/* @Override */
	protected void applyCallback() {
		applyChanges();
	}

	private bool applyChanges() {
		if (listener != null) {
			listener.beforeChangesApplied();
		}
		try {
			if (panel.apply()) {
				setHasChanges(false);
				return true;
			}
		}
		finally {
			if (listener != null) {
				listener.changesApplied();
			}
		}
		return false;
	}

	public void displayCategory(string category, string filterText) {
		if (panel != null) {
			panel.displayCategory(category, filterText);
		}
	}

//=========================================================
// Inner Classes
//=========================================================

	class OptionsPropertyChangeListener : PropertyChangeListener {
		/* @Override */
		public void propertyChange(PropertyChangeEvent evt) {
			if (evt.getPropertyName().equals("apply.enabled")) {
				setHasChanges((Boolean) evt.getNewValue());
			}
		}
	}
}
